import {
  CommerceError,
  commerceProductSchema,
  commerceSnapshotSchema,
  type CommerceAction,
  type CommerceBilling,
  type CommerceProduct,
  type CommerceSnapshot,
} from "./commerce";

export const COMMERCE_STORAGE_PREFIX = "aureform:commerce:v1:";
export const commercePlans = [
  { name: "Starter", amount: 9900 },
  { name: "Pro", amount: 24900 },
  { name: "Enterprise", amount: 69900 },
] as const;

export function parseCommerceSnapshot(value: unknown): CommerceSnapshot | null {
  const parsed = commerceSnapshotSchema.safeParse(value);
  if (!parsed.success) return null;
  const snapshot = parsed.data;
  for (const records of [
    snapshot.products,
    snapshot.orders,
    snapshot.invoices,
  ]) {
    if (new Set(records.map((item) => item.id)).size !== records.length)
      return null;
  }
  if (
    new Set(snapshot.products.map((item) => item.sku.toLowerCase())).size !==
    snapshot.products.length
  )
    return null;
  if (
    snapshot.products.some(
      (item) =>
        new Set(item.images.map((image) => image.id)).size !==
        item.images.length,
    )
  )
    return null;
  if (
    snapshot.orders.some(
      (order) =>
        order.total !==
        order.items.reduce(
          (sum, item) => sum + item.unitAmount * item.quantity,
          0,
        ),
    )
  )
    return null;
  return snapshot;
}

/** A changed amount/currency needs a new Stripe Price; never reuse the old id. */
export function upsertCommerceProduct(
  snapshot: CommerceSnapshot,
  candidate: CommerceProduct,
  now: string,
): CommerceSnapshot {
  const validated = commerceProductSchema.safeParse(candidate);
  if (!validated.success)
    throw new CommerceError("validation", "Check the product fields.");
  const product = validated.data;
  if (
    snapshot.products.some(
      (item) =>
        item.id !== product.id &&
        item.sku.toLowerCase() === product.sku.toLowerCase(),
    )
  ) {
    throw new CommerceError(
      "conflict",
      "Another product already uses this SKU.",
    );
  }
  const previous = snapshot.products.find((item) => item.id === product.id);
  if (!previous && snapshot.products.length >= 500) {
    throw new CommerceError("conflict", "The demo catalog is full.");
  }
  const changedPrice =
    previous &&
    (previous.unitAmount !== product.unitAmount ||
      previous.currency !== product.currency);
  const { stripePriceId, ...fields } = product;
  const next: CommerceProduct = {
    ...fields,
    ...(stripePriceId &&
    (!changedPrice || stripePriceId !== previous?.stripePriceId)
      ? { stripePriceId }
      : {}),
    updatedAt: now,
  };
  return {
    ...snapshot,
    products: previous
      ? snapshot.products.map((item) => (item.id === next.id ? next : item))
      : [next, ...snapshot.products],
  };
}

/** Applies a demo payment once. Failed payments never consume stock. */
export function completeMockCheckout(
  snapshot: CommerceSnapshot,
  action: Extract<CommerceAction, { mode: "mock" }>,
  outcome: "paid" | "failed",
  now: string,
): CommerceSnapshot {
  if (action.kind === "portal") {
    throw new CommerceError(
      "validation",
      "The customer portal does not accept a payment.",
    );
  }
  if (action.kind === "order") {
    const order = snapshot.orders.find((item) => item.id === action.id);
    if (
      !order ||
      order.status === "cancelled" ||
      order.paymentStatus === "refunded"
    ) {
      throw new CommerceError("unavailable", "This order cannot be paid.");
    }
    if (order.paymentStatus === "paid") return snapshot;
    if (outcome === "failed")
      return {
        ...snapshot,
        orders: snapshot.orders.map((item) =>
          item.id === order.id ? { ...item, paymentStatus: "failed" } : item,
        ),
      };
    const quantities = new Map<string, number>();
    for (const line of order.items) {
      quantities.set(
        line.productId,
        (quantities.get(line.productId) ?? 0) + line.quantity,
      );
    }
    for (const [productId, quantity] of quantities) {
      const product = snapshot.products.find((item) => item.id === productId);
      if (
        !product ||
        product.status !== "active" ||
        product.inventory < quantity
      ) {
        throw new CommerceError(
          "conflict",
          "Inventory changed. Review the order before paying.",
        );
      }
    }
    const invoiceId = `inv-order-${order.id}`;
    return {
      ...snapshot,
      products: snapshot.products.map((product) => ({
        ...product,
        inventory: product.inventory - (quantities.get(product.id) ?? 0),
      })),
      orders: snapshot.orders.map((item) =>
        item.id === order.id ? { ...item, paymentStatus: "paid" } : item,
      ),
      invoices: snapshot.invoices.some((item) => item.id === invoiceId)
        ? snapshot.invoices
        : [
            {
              id: invoiceId,
              number: `INV-${order.number.replace("#", "")}`,
              customerName: order.customerName,
              customerEmail: order.customerEmail,
              description: `Order ${order.number}`,
              amount: order.total,
              currency: order.currency,
              status: "paid",
              issuedAt: now,
              dueAt: now,
            },
            ...snapshot.invoices,
          ],
    };
  }
  if (action.kind === "invoice") {
    const invoice = snapshot.invoices.find((item) => item.id === action.id);
    if (!invoice || invoice.status === "draft" || invoice.status === "void") {
      throw new CommerceError("unavailable", "This invoice cannot be paid.");
    }
    if (invoice.status === "paid" || outcome === "failed") return snapshot;
    return {
      ...snapshot,
      invoices: snapshot.invoices.map((item) =>
        item.id === invoice.id ? { ...item, status: "paid" } : item,
      ),
    };
  }
  const plan = commercePlans.find((item) => item.name === action.id);
  if (!plan) throw new CommerceError("validation", "Choose an available plan.");
  if (outcome === "failed") return snapshot;
  if (
    snapshot.billing.plan === plan.name &&
    snapshot.billing.status === "active"
  )
    return snapshot;
  const period = new Date(now);
  period.setUTCMonth(period.getUTCMonth() + 1);
  const billing: CommerceBilling = {
    ...snapshot.billing,
    plan: plan.name,
    amount: plan.amount,
    status: "active",
    interval: "month",
    currentPeriodEnd: period.toISOString(),
  };
  return {
    ...snapshot,
    billing,
    invoices: [
      {
        id: `inv-plan-${plan.name.toLowerCase()}-${Date.parse(now)}`,
        number: `SUB-${Date.parse(now).toString(36).toUpperCase()}`,
        customerName: "Aureform workspace",
        customerEmail: billing.customerEmail,
        description: `${plan.name} subscription`,
        amount: plan.amount,
        currency: billing.currency,
        status: "paid",
        issuedAt: now,
        dueAt: now,
      },
      ...snapshot.invoices,
    ],
  };
}

import { z } from "zod";

export const commerceCurrencies = ["usd", "eur", "gbp"] as const;
export type CommerceCurrency = (typeof commerceCurrencies)[number];
export type ProductStatus = "active" | "draft" | "archived";
export type ProductImage = {
  id: string;
  src: string;
  alt: string;
  width?: number;
  height?: number;
};
/** Amounts are integer minor units. The supported currencies use two decimals. */
export type CommerceProduct = {
  id: string;
  name: string;
  sku: string;
  description: string;
  category: string;
  status: ProductStatus;
  unitAmount: number;
  currency: CommerceCurrency;
  inventory: number;
  images: ProductImage[];
  tags: string[];
  /** Optional display references; the backend owns the actual provider mapping. */
  providerProductId?: string;
  providerPriceId?: string;
  stripeProductId?: string;
  stripePriceId?: string;
  updatedAt: string;
};
export type OrderLine = {
  productId: string;
  name: string;
  quantity: number;
  unitAmount: number;
  image?: string;
};
export type CommerceOrder = {
  id: string;
  number: string;
  customerName: string;
  customerEmail: string;
  currency: CommerceCurrency;
  total: number;
  status: "processing" | "shipped" | "delivered" | "cancelled";
  paymentStatus: "unpaid" | "paid" | "failed" | "refunded";
  items: OrderLine[];
  createdAt: string;
  shippingAddress: string;
  providerSessionId?: string;
  stripeSessionId?: string;
};
export type CommerceInvoice = {
  id: string;
  number: string;
  customerName: string;
  customerEmail: string;
  description: string;
  amount: number;
  currency: CommerceCurrency;
  status: "draft" | "open" | "paid" | "overdue" | "void";
  issuedAt: string;
  dueAt: string;
  providerInvoiceId?: string;
  stripeInvoiceId?: string;
};
export type CommerceBilling = {
  plan: "Starter" | "Pro" | "Enterprise";
  status: "active" | "trialing" | "past_due" | "cancelled";
  amount: number;
  currency: CommerceCurrency;
  interval: "month" | "year";
  currentPeriodEnd: string;
  cardBrand: string;
  /** Empty when the provider does not expose card details. */
  cardLast4: string;
  customerEmail: string;
  providerCustomerId?: string;
  stripeCustomerId?: string;
};
export type CommerceSnapshot = {
  version: 1;
  products: CommerceProduct[];
  orders: CommerceOrder[];
  invoices: CommerceInvoice[];
  billing: CommerceBilling;
};
export type NewOrderInput = {
  customerName: string;
  customerEmail: string;
  shippingAddress?: string;
  items: { productId: string; quantity: number }[];
};
export type NewInvoiceInput = {
  customerName: string;
  customerEmail: string;
  description: string;
  amount: number;
  currency: CommerceCurrency;
  dueAt: string;
};
export type CheckoutRequest = {
  kind: "order" | "invoice" | "subscription";
  id: string;
};
export type CommerceAction =
  | { mode: "mock"; kind: CheckoutRequest["kind"] | "portal"; id: string }
  | { mode: "redirect"; url: string };
export type CommerceScope = { workspaceId: string; signal?: AbortSignal };
export type CommerceProviderIdentity = { id: string; label: string };

/** Implement this contract on your own authenticated backend. */
export type CommerceAdapter = {
  mode: "stripe" | "provider";
  /** Legacy Stripe adapters can omit these fields and retain their old policy. */
  provider?: CommerceProviderIdentity;
  /** Required for provider mode; exact HTTPS origins, with no wildcard hosts. */
  trustedRedirectOrigins?: readonly string[];
  load: (scope: CommerceScope) => Promise<CommerceSnapshot>;
  saveProduct: (
    product: CommerceProduct,
    scope: CommerceScope,
  ) => Promise<CommerceProduct>;
  archiveProduct: (
    productId: string,
    scope: CommerceScope,
  ) => Promise<CommerceProduct>;
  syncProduct: (
    productId: string,
    scope: CommerceScope,
  ) => Promise<CommerceProduct>;
  createOrder: (
    input: NewOrderInput,
    scope: CommerceScope,
  ) => Promise<CommerceOrder>;
  updateOrderStatus: (
    orderId: string,
    status: CommerceOrder["status"],
    scope: CommerceScope,
  ) => Promise<CommerceOrder>;
  createInvoice: (
    input: NewInvoiceInput,
    scope: CommerceScope,
  ) => Promise<CommerceInvoice>;
  checkout: (
    input: CheckoutRequest,
    scope: CommerceScope,
  ) => Promise<CommerceAction>;
  portal: (scope: CommerceScope) => Promise<CommerceAction>;
};

export type CommerceContextValue = CommerceSnapshot & {
  ready: boolean;
  busy: string | null;
  mode: "mock" | CommerceAdapter["mode"];
  provider?: CommerceProviderIdentity;
  error: CommerceError | null;
  persistenceError: "read" | "write" | "invalid" | null;
  canWrite: boolean;
  canManageBilling: boolean;
  reload: () => Promise<void>;
  retryPersistence: () => void;
  saveProduct: (product: CommerceProduct) => Promise<CommerceProduct>;
  archiveProduct: (id: string) => Promise<CommerceProduct>;
  syncProduct: (id: string) => Promise<CommerceProduct>;
  createOrder: (input: NewOrderInput) => Promise<CommerceOrder>;
  updateOrderStatus: (
    id: string,
    status: CommerceOrder["status"],
  ) => Promise<CommerceOrder>;
  createInvoice: (input: NewInvoiceInput) => Promise<CommerceInvoice>;
  checkoutOrder: (id: string) => Promise<CommerceAction>;
  payInvoice: (id: string) => Promise<CommerceAction>;
  checkoutPlan: (plan: CommerceBilling["plan"]) => Promise<CommerceAction>;
  openPortal: () => Promise<CommerceAction>;
  simulateCheckout: (
    action: Extract<CommerceAction, { mode: "mock" }>,
    outcome: "paid" | "failed",
  ) => Promise<void>;
};

/** Shared by connected views; legacy Stripe contexts keep their display name. */
export function getCommerceProviderLabel(
  value: Pick<CommerceContextValue, "mode" | "provider">,
) {
  return (
    value.provider?.label ??
    (value.mode === "mock"
      ? "Demo"
      : value.mode === "stripe"
        ? "Stripe"
        : "Commerce")
  );
}

const integerAmount = z.number().int().nonnegative().max(100_000_000);
const identifier = z.string().trim().min(1).max(100);
const currency = z.enum(commerceCurrencies);
export function isProductImageSource(src: string) {
  if (src.startsWith("/") && !src.startsWith("//") && !src.includes("\\")) {
    return !src.includes("..");
  }
  if (/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(src)) {
    return src.length <= 1_000_000;
  }
  try {
    return new URL(src).protocol === "https:";
  } catch {
    return false;
  }
}
export const productImageSchema = z.object({
  id: identifier,
  src: z
    .string()
    .refine(isProductImageSource, "Use a local, HTTPS or prepared image."),
  alt: z.string().trim().min(1).max(240),
  width: z.number().int().positive().max(16384).optional(),
  height: z.number().int().positive().max(16384).optional(),
});
export const commerceProductSchema = z.object({
  id: identifier,
  name: z.string().trim().min(2).max(140),
  sku: z.string().trim().min(2).max(64),
  description: z.string().trim().max(5000),
  category: z.string().trim().min(1).max(80),
  status: z.enum(["active", "draft", "archived"]),
  unitAmount: integerAmount,
  currency,
  inventory: z.number().int().nonnegative().max(1_000_000),
  images: z.array(productImageSchema).max(6),
  tags: z.array(z.string().trim().min(1).max(40)).max(12),
  providerProductId: identifier.optional(),
  providerPriceId: identifier.optional(),
  stripeProductId: identifier.optional(),
  stripePriceId: identifier.optional(),
  updatedAt: z.iso.datetime(),
});
const orderLineSchema = z.object({
  productId: identifier,
  name: z.string().min(1).max(140),
  quantity: z.number().int().min(1).max(999),
  unitAmount: integerAmount,
  image: z.string().refine(isProductImageSource).optional(),
});
export const commerceOrderSchema = z.object({
  id: identifier,
  number: z.string().min(1).max(40),
  customerName: z.string().trim().min(2).max(140),
  customerEmail: z.email(),
  currency,
  total: integerAmount,
  status: z.enum(["processing", "shipped", "delivered", "cancelled"]),
  paymentStatus: z.enum(["unpaid", "paid", "failed", "refunded"]),
  items: z.array(orderLineSchema).min(1).max(50),
  createdAt: z.iso.datetime(),
  shippingAddress: z.string().max(500),
  providerSessionId: identifier.optional(),
  stripeSessionId: identifier.optional(),
});
export const commerceInvoiceSchema = z.object({
  id: identifier,
  number: z.string().min(1).max(40),
  customerName: z.string().trim().min(2).max(140),
  customerEmail: z.email(),
  description: z.string().max(1000),
  amount: integerAmount,
  currency,
  status: z.enum(["draft", "open", "paid", "overdue", "void"]),
  issuedAt: z.iso.datetime(),
  dueAt: z.iso.datetime(),
  providerInvoiceId: identifier.optional(),
  stripeInvoiceId: identifier.optional(),
});
export const commerceBillingSchema = z.object({
  plan: z.enum(["Starter", "Pro", "Enterprise"]),
  status: z.enum(["active", "trialing", "past_due", "cancelled"]),
  amount: integerAmount,
  currency,
  interval: z.enum(["month", "year"]),
  currentPeriodEnd: z.iso.datetime(),
  cardBrand: z.string().min(1).max(40),
  cardLast4: z.string().regex(/^(?:\d{4})?$/),
  customerEmail: z.email(),
  providerCustomerId: identifier.optional(),
  stripeCustomerId: identifier.optional(),
});
export const commerceSnapshotSchema = z.object({
  version: z.literal(1),
  products: z.array(commerceProductSchema).max(500),
  orders: z.array(commerceOrderSchema).max(1000),
  invoices: z.array(commerceInvoiceSchema).max(1000),
  billing: commerceBillingSchema,
});
export const newOrderSchema = z.object({
  customerName: z.string().trim().min(2).max(140),
  customerEmail: z.email(),
  shippingAddress: z.string().trim().max(500).optional(),
  items: z
    .array(
      z.object({
        productId: identifier,
        quantity: z.number().int().min(1).max(999),
      }),
    )
    .min(1)
    .max(50),
});
export const newInvoiceSchema = z.object({
  customerName: z.string().trim().min(2).max(140),
  customerEmail: z.email(),
  description: z.string().trim().min(2).max(1000),
  amount: integerAmount,
  currency,
  dueAt: z.iso.datetime(),
});

export class CommerceError extends Error {
  readonly code:
    "validation" | "unavailable" | "conflict" | "forbidden" | "provider";
  constructor(code: CommerceError["code"], message: string) {
    super(message);
    this.name = "CommerceError";
    this.code = code;
  }
}

export function buildOrder(
  input: NewOrderInput,
  products: readonly CommerceProduct[],
  id: string,
  createdAt: string,
): CommerceOrder {
  const result = newOrderSchema.safeParse(input);
  if (!result.success)
    throw new CommerceError("validation", "Check the order fields.");
  const merged = new Map<string, number>();
  for (const line of result.data.items) {
    merged.set(
      line.productId,
      (merged.get(line.productId) ?? 0) + line.quantity,
    );
  }
  let orderCurrency: CommerceCurrency | undefined;
  const items = [...merged].map(([productId, quantity]) => {
    const product = products.find((item) => item.id === productId);
    if (!product || product.status !== "active") {
      throw new CommerceError(
        "unavailable",
        "The selected product is unavailable.",
      );
    }
    if (quantity > 999 || quantity > product.inventory) {
      throw new CommerceError("conflict", "There is not enough inventory.");
    }
    if (orderCurrency && orderCurrency !== product.currency) {
      throw new CommerceError("validation", "Use one currency per order.");
    }
    orderCurrency = product.currency;
    return {
      productId,
      name: product.name,
      quantity,
      unitAmount: product.unitAmount,
      ...(product.images[0] ? { image: product.images[0].src } : {}),
    };
  });
  const order: CommerceOrder = {
    id,
    number: `#${id.replace(/^ord-/, "").slice(0, 12).toUpperCase()}`,
    customerName: result.data.customerName,
    customerEmail: result.data.customerEmail,
    currency: orderCurrency ?? "usd",
    total: items.reduce(
      (sum, item) => sum + item.unitAmount * item.quantity,
      0,
    ),
    status: "processing",
    paymentStatus: "unpaid",
    items,
    createdAt,
    shippingAddress: result.data.shippingAddress ?? "",
  };
  const validated = commerceOrderSchema.safeParse(order);
  if (!validated.success)
    throw new CommerceError("validation", "The order total is out of range.");
  return validated.data;
}

import { z } from "zod";
import {
  CommerceError,
  commerceBillingSchema,
  commerceInvoiceSchema,
  commerceOrderSchema,
  commerceProductSchema,
  newInvoiceSchema,
  newOrderSchema,
  type CheckoutRequest,
  type CommerceAction,
  type CommerceAdapter,
  type CommerceOrder,
  type CommerceProduct,
  type CommerceProviderIdentity,
  type CommerceScope,
  type CommerceSnapshot,
  type NewInvoiceInput,
  type NewOrderInput,
} from "./commerce";
import { parseCommerceSnapshot } from "./commerce-state";
import { publicPath } from "./public-path";

export const commerceProviderLabels = {
  stripe: "Stripe",
  paddle: "Paddle",
  polar: "Polar",
  "lemon-squeezy": "Lemon Squeezy",
} as const;

export type CommerceProviderName = keyof typeof commerceProviderLabels;
export type CommerceProviderSelection =
  | CommerceProviderName
  | "lemonsqueezy"
  | "lemonSqueezy"
  | "lemon_squeezy"
  | CommerceProviderIdentity;

export type ProviderCommerceTransportOptions = {
  /** A same-origin API path; defaults to the build-mounted /api/commerce. */
  baseUrl?: string;
  /** No built-in provider domains. Configure your actual checkout/portal origins. */
  trustedRedirectOrigins: readonly string[];
  /** When supplied, every mutation requires a nonempty token from this getter. */
  getCsrfToken?: () => string | null | Promise<string | null>;
  /** Consumer transport override, also useful for deterministic native mocks. */
  fetcher?: typeof fetch;
};
export type ProviderCommerceOptions = ProviderCommerceTransportOptions & {
  provider: CommerceProviderSelection;
};
export type ProviderCommerceAdapter = CommerceAdapter & {
  mode: "provider";
  provider: CommerceProviderIdentity;
  trustedRedirectOrigins: readonly string[];
};

export type ProviderCommerceScope = { workspaceId: string; provider: string };
export type ProviderCommerceProductInput = Omit<
  CommerceProduct,
  "providerProductId" | "providerPriceId" | "stripeProductId" | "stripePriceId"
>;
/** The JSON request contract, including server-authorized scope and provider. */
export type ProviderCommerceRequests = {
  load: ProviderCommerceScope;
  saveProduct: ProviderCommerceScope & {
    product: ProviderCommerceProductInput;
  };
  archiveProduct: ProviderCommerceScope & { productId: string };
  syncProduct: ProviderCommerceScope & { productId: string };
  createOrder: ProviderCommerceScope & { input: NewOrderInput };
  updateOrderStatus: ProviderCommerceScope & {
    orderId: string;
    status: CommerceOrder["status"];
  };
  createInvoice: ProviderCommerceScope & { input: NewInvoiceInput };
  checkout: ProviderCommerceScope & CheckoutRequest;
  portal: ProviderCommerceScope;
};

const identifier = z.string().trim().min(1).max(100);
const checkoutSchema = z.object({
  kind: z.enum(["order", "invoice", "subscription"]),
  id: identifier,
});
const orderStatusSchema = commerceOrderSchema.shape.status;
const invalidRecord = () =>
  new CommerceError(
    "provider",
    "The commerce backend returned an invalid record.",
  );
const cancelled = () =>
  new CommerceError("conflict", "The request was cancelled.");

/** Known aliases normalize only provider identity, never payment/customer IDs. */
export function resolveCommerceProviderIdentity(
  selection: CommerceProviderSelection,
): CommerceProviderIdentity {
  const raw = typeof selection === "string" ? selection : selection?.id;
  if (typeof raw !== "string")
    throw new CommerceError("validation", "Choose a commerce provider.");
  let id = raw.trim().toLowerCase();
  if (["lemonsqueezy", "lemon_squeezy"].includes(id)) id = "lemon-squeezy";
  if (!/^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/.test(id) || id.length > 100)
    throw new CommerceError("validation", "Use a stable commerce provider id.");
  const known = commerceProviderLabels[id as CommerceProviderName];
  const label = typeof selection === "string" ? known : selection.label;
  if (
    typeof label !== "string" ||
    !label.trim() ||
    label.length > 80 ||
    /[\u0000-\u001f\u007f]/.test(label)
  )
    throw new CommerceError(
      "validation",
      "Supply a commerce provider display label.",
    );
  return { id, label: label.trim() };
}

function parseHttpsUrl(value: unknown): URL | null {
  if (
    typeof value !== "string" ||
    !/^https:\/\/[^/?#]/i.test(value) ||
    /[\s\\]/u.test(value) ||
    /^https:\/\/[^/?#]*[@%*]/i.test(value)
  )
    return null;
  try {
    const url = new URL(value);
    return url.protocol === "https:" &&
      !url.username &&
      !url.password &&
      !url.hostname.endsWith(".")
      ? url
      : null;
  } catch {
    return null;
  }
}

export function normalizeCommerceRedirectOrigins(
  origins: readonly string[],
): readonly string[] {
  if (!Array.isArray(origins) || origins.length === 0)
    throw new CommerceError(
      "validation",
      "Configure trusted HTTPS checkout and customer portal origins.",
    );
  const normalized = origins.map((origin) => {
    const url = parseHttpsUrl(origin);
    if (!url || !/^https:\/\/[^/?#]+\/?$/i.test(origin) || url.pathname !== "/")
      throw new CommerceError(
        "validation",
        "Use exact HTTPS origins without paths, credentials or wildcards.",
      );
    return url.origin;
  });
  return Object.freeze([...new Set(normalized)]);
}

export function isTrustedCommerceRedirect(
  value: unknown,
  trustedOrigins: readonly string[],
): boolean {
  const url = parseHttpsUrl(value);
  if (!url) return false;
  try {
    return normalizeCommerceRedirectOrigins(trustedOrigins).includes(
      url.origin,
    );
  } catch {
    return false;
  }
}

export function parseProviderCommerceAction(
  value: unknown,
  trustedOrigins: readonly string[],
): Extract<CommerceAction, { mode: "redirect" }> {
  if (
    typeof value !== "object" ||
    value === null ||
    !("mode" in value) ||
    value.mode !== "redirect" ||
    !("url" in value) ||
    !isTrustedCommerceRedirect(value.url, trustedOrigins)
  )
    throw new CommerceError(
      "provider",
      "The backend returned an untrusted commerce redirect.",
    );
  return { mode: "redirect", url: new URL(value.url as string).href };
}

function validOrderRelationships(order: CommerceOrder) {
  return (
    new Set(order.items.map((item) => item.productId)).size ===
      order.items.length &&
    order.total ===
      order.items.reduce(
        (sum, item) => sum + item.unitAmount * item.quantity,
        0,
      ) &&
    (!["shipped", "delivered"].includes(order.status) ||
      ["paid", "refunded"].includes(order.paymentStatus))
  );
}

/** Historical prices remain independent of today's catalog; IDs must still exist. */
export function parseProviderCommerceSnapshot(
  value: unknown,
): CommerceSnapshot | null {
  const snapshot = parseCommerceSnapshot(value);
  if (!snapshot) return null;
  const productIds = new Set(snapshot.products.map((product) => product.id));
  if (
    snapshot.orders.some(
      (order) =>
        !validOrderRelationships(order) ||
        order.items.some((line) => !productIds.has(line.productId)),
    )
  )
    return null;
  return snapshot;
}

function parseIdentifier(value: unknown, label: string) {
  const parsed = identifier.safeParse(value);
  if (!parsed.success)
    throw new CommerceError("validation", `Choose a valid ${label}.`);
  return parsed.data;
}

function checkCancellation(signal?: AbortSignal) {
  if (signal?.aborted) throw cancelled();
}

/** Reject promptly even when a custom fetcher/CSRF getter ignores AbortSignal. */
function withCancellation<T>(
  operation: () => T | PromiseLike<T>,
  signal?: AbortSignal,
): Promise<T> {
  checkCancellation(signal);
  return new Promise<T>((resolve, reject) => {
    const abort = () => {
      signal?.removeEventListener("abort", abort);
      reject(cancelled());
    };
    signal?.addEventListener("abort", abort, { once: true });
    const finish = () => signal?.removeEventListener("abort", abort);
    try {
      checkCancellation(signal);
      Promise.resolve(operation()).then(
        (result) => {
          finish();
          if (signal?.aborted) reject(cancelled());
          else resolve(result);
        },
        (error: unknown) => {
          finish();
          reject(signal?.aborted ? cancelled() : error);
        },
      );
    } catch (error) {
      finish();
      reject(error);
    }
  });
}

const statusErrors: Record<number, [CommerceError["code"], string]> = {
  400: ["validation", "Check the submitted fields."],
  401: ["forbidden", "Sign in to your application before continuing."],
  403: ["forbidden", "Your account cannot perform this action."],
  404: ["unavailable", "The requested record is no longer available."],
  409: ["conflict", "The record changed. Reload before trying again."],
  422: ["validation", "Check the submitted fields."],
  429: ["provider", "Too many requests. Try again shortly."],
};

/**
 * Consumer HTTP transport. Provider SDKs, secrets, prices, customer mappings,
 * payment status and webhook fulfillment stay on the authenticated backend.
 */
export function createProviderCommerceAdapter(
  options: ProviderCommerceOptions,
): ProviderCommerceAdapter {
  const provider = Object.freeze(
    resolveCommerceProviderIdentity(options?.provider),
  );
  const trustedRedirectOrigins = normalizeCommerceRedirectOrigins(
    options.trustedRedirectOrigins,
  );
  const configuredPath = options.baseUrl ?? publicPath("/api/commerce");
  if (typeof configuredPath !== "string")
    throw new CommerceError(
      "validation",
      "Use a same-origin commerce API path.",
    );
  const baseUrl = configuredPath.replace(/\/+$/, "");
  if (
    !/^\/[A-Za-z0-9/_.-]+$/.test(baseUrl) ||
    baseUrl.startsWith("//") ||
    baseUrl.split("/").some((segment) => segment === "." || segment === "..")
  )
    throw new CommerceError(
      "validation",
      "Use a same-origin commerce API path.",
    );
  const fetcher =
    options.fetcher ?? ((...args: Parameters<typeof fetch>) => fetch(...args));
  const scopeBody = (scope: CommerceScope): ProviderCommerceScope => ({
    workspaceId: parseIdentifier(scope?.workspaceId, "workspace"),
    provider: provider.id,
  });

  async function request(
    path: string,
    scope: CommerceScope,
    body?: ProviderCommerceRequests[Exclude<
      keyof ProviderCommerceRequests,
      "load"
    >],
  ): Promise<unknown> {
    checkCancellation(scope.signal);
    let csrf: string | null = null;
    if (body !== undefined && options.getCsrfToken) {
      try {
        csrf = await withCancellation(options.getCsrfToken, scope.signal);
      } catch {
        checkCancellation(scope.signal);
        throw new CommerceError(
          "provider",
          "The CSRF token could not be read. Refresh and try again.",
        );
      }
      if (typeof csrf !== "string" || !/^[\x21-\x7e]{1,4096}$/.test(csrf))
        throw new CommerceError(
          "forbidden",
          "A valid CSRF token is required for this request.",
        );
    }
    let response: Response;
    try {
      response = await withCancellation(
        () =>
          fetcher(`${baseUrl}${path}`, {
            method: body === undefined ? "GET" : "POST",
            credentials: "same-origin",
            mode: "same-origin",
            redirect: "error",
            cache: "no-store",
            signal: scope.signal,
            headers: {
              Accept: "application/json",
              "X-Aureform-Request": "commerce",
              ...(body === undefined
                ? {}
                : { "Content-Type": "application/json" }),
              ...(csrf ? { "X-CSRF-Token": csrf } : {}),
            },
            ...(body === undefined ? {} : { body: JSON.stringify(body) }),
          }),
        scope.signal,
      );
    } catch {
      checkCancellation(scope.signal);
      throw new CommerceError(
        "provider",
        "The commerce backend is unavailable. Try again.",
      );
    }
    checkCancellation(scope.signal);
    if (response.redirected || response.type === "opaqueredirect")
      throw new CommerceError(
        "provider",
        "The commerce API must not redirect requests.",
      );
    if (!response.ok) {
      const [code, message] = statusErrors[response.status] ?? [
        "provider",
        "The commerce backend could not complete the request.",
      ];
      throw new CommerceError(code, message);
    }
    const mediaType = response.headers
      .get("content-type")
      ?.split(";")[0]
      .trim();
    if (
      !mediaType ||
      !/^application\/(?:[\w!#$&^.+-]+\+)?json$/i.test(mediaType)
    )
      throw new CommerceError(
        "provider",
        "The commerce backend must return JSON.",
      );
    try {
      return await withCancellation(
        () => response.json() as Promise<unknown>,
        scope.signal,
      );
    } catch {
      checkCancellation(scope.signal);
      throw new CommerceError(
        "provider",
        "The commerce backend returned invalid JSON.",
      );
    }
  }

  function parseProduct(value: unknown, id: string, archived = false) {
    const result = commerceProductSchema.safeParse(value);
    if (
      !result.success ||
      result.data.id !== id ||
      (archived && result.data.status !== "archived") ||
      new Set(result.data.images.map((image) => image.id)).size !==
        result.data.images.length
    )
      throw invalidRecord();
    return result.data;
  }

  function parseOrder(value: unknown) {
    const result = commerceOrderSchema.safeParse(value);
    if (!result.success || !validOrderRelationships(result.data))
      throw invalidRecord();
    return result.data;
  }

  return {
    mode: "provider",
    provider,
    trustedRedirectOrigins,
    async load(scope) {
      const query = new URLSearchParams(scopeBody(scope));
      const snapshot = parseProviderCommerceSnapshot(
        await request(`?${query}`, scope),
      );
      if (!snapshot) throw invalidRecord();
      return snapshot;
    },
    async saveProduct(product, scope) {
      const input = commerceProductSchema.safeParse(product);
      if (
        !input.success ||
        new Set(input.data.images.map((image) => image.id)).size !==
          input.data.images.length
      )
        throw new CommerceError("validation", "Check the product fields.");
      // Do not let editable display references select provider resources.
      const fields = { ...input.data };
      delete fields.providerProductId;
      delete fields.providerPriceId;
      delete fields.stripeProductId;
      delete fields.stripePriceId;
      return parseProduct(
        await request("/products/save", scope, {
          ...scopeBody(scope),
          product: fields,
        }),
        fields.id,
      );
    },
    async archiveProduct(productId, scope) {
      const id = parseIdentifier(productId, "product");
      return parseProduct(
        await request("/products/archive", scope, {
          ...scopeBody(scope),
          productId: id,
        }),
        id,
        true,
      );
    },
    async syncProduct(productId, scope) {
      const id = parseIdentifier(productId, "product");
      return parseProduct(
        await request("/products/sync", scope, {
          ...scopeBody(scope),
          productId: id,
        }),
        id,
      );
    },
    async createOrder(input, scope) {
      const parsed = newOrderSchema.safeParse(input);
      if (!parsed.success)
        throw new CommerceError("validation", "Check the order fields.");
      const quantities = new Map<string, number>();
      for (const item of parsed.data.items)
        quantities.set(
          item.productId,
          (quantities.get(item.productId) ?? 0) + item.quantity,
        );
      if ([...quantities.values()].some((quantity) => quantity > 999))
        throw new CommerceError("validation", "Check the order quantities.");
      const normalized = {
        ...parsed.data,
        items: [...quantities].map(([productId, quantity]) => ({
          productId,
          quantity,
        })),
      };
      const result = parseOrder(
        await request("/orders/create", scope, {
          ...scopeBody(scope),
          input: normalized,
        }),
      );
      if (
        result.items.length !== quantities.size ||
        result.items.some(
          (item) => quantities.get(item.productId) !== item.quantity,
        ) ||
        result.customerEmail.toLowerCase() !==
          normalized.customerEmail.toLowerCase()
      )
        throw invalidRecord();
      return result;
    },
    async updateOrderStatus(orderId, status, scope) {
      const id = parseIdentifier(orderId, "order");
      const parsed = orderStatusSchema.safeParse(status);
      if (!parsed.success)
        throw new CommerceError(
          "validation",
          "Choose an available order status.",
        );
      const result = parseOrder(
        await request("/orders/status", scope, {
          ...scopeBody(scope),
          orderId: id,
          status: parsed.data,
        }),
      );
      if (result.id !== id || result.status !== parsed.data)
        throw invalidRecord();
      return result;
    },
    async createInvoice(input, scope) {
      const parsed = newInvoiceSchema.safeParse(input);
      if (!parsed.success)
        throw new CommerceError("validation", "Check the invoice fields.");
      const result = commerceInvoiceSchema.safeParse(
        await request("/invoices/create", scope, {
          ...scopeBody(scope),
          input: parsed.data,
        }),
      );
      if (
        !result.success ||
        result.data.currency !== parsed.data.currency ||
        result.data.customerEmail.toLowerCase() !==
          parsed.data.customerEmail.toLowerCase()
      )
        throw invalidRecord();
      return result.data;
    },
    async checkout(input, scope) {
      const parsed = checkoutSchema.safeParse(input);
      if (
        !parsed.success ||
        (parsed.data.kind === "subscription" &&
          !commerceBillingSchema.shape.plan.safeParse(parsed.data.id).success)
      )
        throw new CommerceError(
          "validation",
          "Choose an available checkout record.",
        );
      return parseProviderCommerceAction(
        await request("/checkout", scope, {
          ...scopeBody(scope),
          ...parsed.data,
        }),
        trustedRedirectOrigins,
      );
    },
    async portal(scope) {
      return parseProviderCommerceAction(
        await request("/portal", scope, scopeBody(scope)),
        trustedRedirectOrigins,
      );
    },
  };
}

export function createPaddleCommerceAdapter(
  options: ProviderCommerceTransportOptions,
): ProviderCommerceAdapter {
  return createProviderCommerceAdapter({ ...options, provider: "paddle" });
}

export function createPolarCommerceAdapter(
  options: ProviderCommerceTransportOptions,
): ProviderCommerceAdapter {
  return createProviderCommerceAdapter({ ...options, provider: "polar" });
}

export function createLemonSqueezyCommerceAdapter(
  options: ProviderCommerceTransportOptions,
): ProviderCommerceAdapter {
  return createProviderCommerceAdapter({
    ...options,
    provider: "lemon-squeezy",
  });
}

/**
 * Add the build's mount point to a public asset or native HTML link.
 * Keep next/link and Next's router paths unprefixed: Next handles those itself.
 */
export function publicPath(
  path: string,
  basePath = process.env.NEXT_PUBLIC_BASE_PATH ?? "",
): string {
  if (!path.startsWith("/") || path.startsWith("//")) return path;
  const prefix = basePath.trim().replace(/^\/+|\/+$/g, "");
  if (!prefix) return path;
  const base = `/${prefix}`;
  if (
    path === base ||
    path.startsWith(`${base}/`) ||
    path.startsWith(`${base}?`) ||
    path.startsWith(`${base}#`)
  ) {
    return path;
  }
  return `${base}${path}`;
}
